.opsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e8ecef;
    background:
        repeating-linear-gradient(45deg, rgba(255,255,255,0.012) 0 14px, transparent 14px 28px),
        linear-gradient(160deg, #20262e 0%, #161b22 55%, #10141a 100%);
    border-radius: 14px;
}

.opsim-container * {
    box-sizing: border-box;
}

.opsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1b2128 0%, #232c34 55%, #2a3540 100%);
    color: #f1f4f6;
    border-radius: 12px;
    margin-bottom: 20px;
    border: 1px solid #323d49;
    border-top: 4px solid #f5a623;
    box-shadow: 0 12px 30px rgba(0, 0, 0, 0.5);
}

.opsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    color: #ffffff;
}

.opsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 700;
    color: #f5a623;
    background: rgba(245, 166, 35, 0.12);
    border: 1px solid rgba(245, 166, 35, 0.32);
    padding: 5px 14px;
    border-radius: 4px;
}

.opsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #c3ccd4;
}

.opsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #9aa7b2;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.opsim-period-counter #currentDay,
.opsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #f5a623;
}

.opsim-round-name {
    background: rgba(245, 166, 35, 0.14);
    color: #f5a623;
    padding: 3px 12px;
    border-radius: 4px;
    font-size: 0.82rem;
    font-weight: 700;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    margin-left: 4px;
}

.opsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ff8a5c;
    background: rgba(255, 138, 92, 0.12);
    border: 1px solid rgba(255, 138, 92, 0.30);
    padding: 4px 12px;
    border-radius: 4px;
}

.opsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.opsim-status-card {
    background: linear-gradient(160deg, #222a33 0%, #181e26 100%);
    border-radius: 8px;
    padding: 16px 16px 14px;
    border: 1px solid #2e3946;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.4);
    border-left: 4px solid #4a5a6a;
}

.opsim-card-otd { border-left-color: #2ec4b6; }
.opsim-card-inv { border-left-color: #4aa3ff; }
.opsim-card-util { border-left-color: #f5a623; }
.opsim-card-cost { border-left-color: #b48bff; }

.opsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    font-weight: 700;
    color: #8493a1;
}

.opsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #ffffff;
    font-variant-numeric: tabular-nums;
}

.opsim-card-otd .opsim-value { color: #2ec4b6; }
.opsim-card-inv .opsim-value { color: #4aa3ff; }
.opsim-card-util .opsim-value { color: #f5a623; }
.opsim-card-cost .opsim-value { color: #b48bff; }

.opsim-sublabel {
    font-size: 0.75rem;
    color: #7a8896;
    line-height: 1.35;
}

/* OTD: green good (>=96), red bad (<85) */
.opsim-otd-good .opsim-value { color: #2ee6a8; }
.opsim-otd-bad .opsim-value { color: #ff6b5e; }
.opsim-otd-bad { border-left-color: #ff6b5e; }

/* Inventory: green near 30d, red bloated */
.opsim-inv-good .opsim-value { color: #2ee6a8; }
.opsim-inv-bad .opsim-value { color: #ff6b5e; }
.opsim-inv-bad { border-left-color: #ff6b5e; }

/* Cost: positive saving green, negative red */
.opsim-cost-positive .opsim-value { color: #2ee6a8; }
.opsim-cost-negative .opsim-value { color: #ff6b5e; }

.opsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #151b22;
    border: 1px solid #2e3946;
    border-left: 4px solid #f5a623;
    color: #d4dde5;
    padding: 10px 18px;
    border-radius: 6px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.opsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f5a623;
}

.opsim-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(160deg, #222a33 0%, #181e26 100%);
    border-left: 5px solid #2ec4b6;
    border-radius: 8px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.35);
}

.opsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.opsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #ffffff;
    margin-bottom: 6px;
}

.opsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #c3ccd4;
}

.opsim-briefing-text strong { color: #2ec4b6; }
.opsim-briefing-text em { color: #f5a623; font-style: italic; }

.opsim-controls {
    background: linear-gradient(160deg, #1c232b 0%, #161c23 100%);
    border-radius: 10px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #2e3946;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.35);
}

.opsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.1rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #ffffff;
    border-bottom: 2px solid #2e3946;
    padding-bottom: 8px;
}

.opsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #d2dbe3;
    margin: 14px 0 6px;
}

.opsim-container select,
.opsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #36434f;
    border-radius: 6px;
    font-size: 0.92rem;
    background-color: #11171e;
    color: #eaf0f5;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.opsim-container select:focus,
.opsim-container input[type="number"]:focus {
    outline: none;
    border-color: #f5a623;
    box-shadow: 0 0 0 3px rgba(245, 166, 35, 0.18);
}

.opsim-container select option {
    background-color: #11171e;
    color: #eaf0f5;
}

.opsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #f5a623;
}

.opsim-range-readout,
.opsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9aa7b2;
    margin-top: 4px;
}

.opsim-range-readout span:nth-child(2),
.opsim-alloc-readout span:nth-child(2) {
    color: #f5a623;
    font-weight: 800;
}

.opsim-hint {
    font-size: 0.8rem;
    color: #7a8896;
    margin-top: 4px;
    line-height: 1.4;
}

.opsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.opsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #11171e;
    border: 1px solid #2a3744;
    border-radius: 6px;
    padding: 8px 12px;
}

.opsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #d2dbe3;
}

.opsim-alloc-row input[type="number"] {
    width: 92px;
    flex: 0 0 92px;
}

.opsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.opsim-container .btn-primary {
    background: linear-gradient(135deg, #c97e12 0%, #f5a623 100%);
    border: none;
    color: #1c1304;
    padding: 11px 26px;
    border-radius: 6px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    box-shadow: 0 8px 18px rgba(245, 166, 35, 0.32);
}

.opsim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.opsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #36434f;
    color: #9aa7b2;
    background: transparent;
}

.opsim-coach {
    background: linear-gradient(160deg, #14201f 0%, #15191f 100%);
    color: #d6e2e0;
    border: 1px solid #2a4040;
    border-left: 5px solid #2ec4b6;
    border-radius: 10px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.35);
}

.opsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #2ec4b6;
    margin-bottom: 8px;
}

.opsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.opsim-coach-body strong { color: #2ec4b6; }
.opsim-coach-body em { color: #f5a623; font-style: italic; }

.opsim-history,
.opsim-chart {
    background: linear-gradient(160deg, #1c232b 0%, #161c23 100%);
    border-radius: 10px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #2e3946;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.35);
}

.opsim-history h3,
.opsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.06rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #ffffff;
}

.opsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #d2dbe3;
}

.opsim-container table#usfHistoryTable th {
    background: #11171e;
    color: #f5a623;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #2a3744;
}

.opsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #232d38;
    color: #c3ccd4;
}

.opsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #151b22;
}

.opsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .opsim-container {
        padding: 14px;
    }
    .opsim-header h1 {
        font-size: 1.6rem;
    }
    .opsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .opsim-value {
        font-size: 2rem;
    }
    .opsim-clock {
        margin-left: 0;
    }
    .opsim-period-counter {
        font-size: 0.88rem;
    }
    .opsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .opsim-alloc-row {
        flex-wrap: wrap;
    }
    .opsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .opsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ============================================================
   v1.1.0 — Completion debrief (append-only, scoped .ops-cm)
   Palette: amber #f5a623 · teal #2ec4b6 · coral #ff6b5e · slate #2e3946
   ============================================================ */
.ops-cm { font-family: inherit; color: #11171e; text-align: left; }
.ops-cm-head { display: flex; align-items: center; gap: 20px; flex-wrap: wrap;
    border-bottom: 3px solid #f5a623; padding-bottom: 14px; margin-bottom: 16px; }
.ops-cm-scorebox { display: flex; flex-direction: column; align-items: center;
    background: #2e3946; color: #fff; border-radius: 12px; padding: 12px 20px; min-width: 130px; }
.ops-cm-score { font-size: 2.6rem; line-height: 1; font-weight: 800; color: #f5a623; }
.ops-cm-score-max { font-size: 1rem; font-weight: 600; opacity: 0.8; margin-left: 2px; color: #fff; }
.ops-cm-score-label { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.06em; opacity: 0.85; margin-top: 4px; }
.ops-cm-tier { font-size: 1.5rem; font-weight: 700; color: #2e3946; flex: 1 1 auto; }
.ops-cm-chips { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 16px; }
.ops-cm-chip { flex: 1 1 180px; display: flex; align-items: center; gap: 8px;
    background: #f4f7f9; border: 1px solid #d2dbe3; border-left: 5px solid #c3ccd4; border-radius: 8px; padding: 9px 12px; }
.ops-cm-chip.is-met { border-left-color: #2ec4b6; }
.ops-cm-chip.is-missed { border-left-color: #ff6b5e; }
.ops-cm-chip-l { font-weight: 600; color: #2e3946; font-size: 0.9rem; }
.ops-cm-badge { margin-left: auto; font-size: 0.68rem; font-weight: 700; text-transform: uppercase;
    letter-spacing: 0.04em; padding: 3px 8px; border-radius: 999px; color: #fff; }
.ops-cm-badge.is-met { background: #2ec4b6; }
.ops-cm-badge.is-missed { background: #ff6b5e; }
.ops-cm-kpis { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 18px; }
.ops-cm-kpi { flex: 1 1 110px; text-align: center; background: #fff; border: 1px solid #d2dbe3;
    border-top: 3px solid #f5a623; border-radius: 8px; padding: 10px 8px; }
.ops-cm-kpi-v { font-size: 1.3rem; font-weight: 800; color: #2e3946; font-variant-numeric: tabular-nums; }
.ops-cm-kpi-l { font-size: 0.7rem; text-transform: uppercase; letter-spacing: 0.04em; color: #5a6675; margin-top: 3px; }
.ops-cm-insights-title { font-weight: 700; color: #2e3946; margin-bottom: 6px; }
.ops-cm-insights ul { margin: 0; padding-left: 20px; }
.ops-cm-insights li { margin-bottom: 7px; line-height: 1.5; }

