(function() {
    'use strict';

    class OpsAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Ops Under Pressure`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Empaques del Trópico S.A.).
            this.REVENUE = 86;            // USD 86M revenue
            this.EBITDA = 11.2;          // ~USD 11.2M EBITDA line (13%)
            this.BUDGET = 6.0;           // USD 6M modernization budget
            this.DIGITAL_SLICE = 3.0;    // USD 3M digitalization sub-budget (R3 must total this)
            this.CONTRACT = 14;          // USD 14M / 2-year contract on offer
            this.OTD_TARGET = 96;        // % on-time delivery target
            this.OTD_START = 81;         // % current OTD
            this.INV_START = 52;         // days of stock (vs 30-day target)
            this.INV_TARGET = 30;        // days target
            this.UTIL_START = 78;        // % average capacity utilization
            this.WC_PER_DAY = 0.06;      // ~USD 60,000 working capital per extra inventory day

            // Concept truths (the lever that addresses the cause, not the symptom).
            this.TRUE_ROOT = `system`;
            this.TRUE_LOOP = `bullwhip`;
            this.TRUE_CONTRACT = `conditional`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    otd: this.OTD_START,       // % on-time delivery
                    inv: this.INV_START,       // days of inventory
                    util: this.UTIL_START,     // % capacity utilization
                    cost: 0,                   // USD M cumulative cost / P&L impact vs status quo (positive = saving)
                    budgetUsed: 0,             // USD M of the USD 6M modernization budget committed
                    capacityFixed: false,      // committed heavy permanent capacity
                    boughtContract: false,     // signed the USD 14M contract
                    resinExposed: true,        // single-sourced resin risk still open
                    bullwhipDamped: false,     // broke the over-react / over-correct loop
                    otdHistory: [this.OTD_START],
                    invHistory: [this.INV_START],
                    utilHistory: [this.UTIL_START],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are deliberately the WRONG-LEANING reflexes from the
                // Common Errors list — a blind click-through must NOT auto-win.
                state.decisions = {
                    root: `capacity`,           // Error: blame capacity, not the system
                    split: 20,                  // under-attributes self-inflicted variability
                    loop: `none`,               // misses the bullwhip
                    contract: `signnow`,        // Error 3: growth before stability
                    mix: 80,                    // Error 1: recency-driven permanent capacity
                    service: `point`,           // plans to a point forecast
                    sop: 0.75, tower: 0.75, mes: 0.75, auto: 0.75, // flat split incl. throughput
                    process: `none`,            // no real S&OP cadence
                    safety: `flat`,             // Error 5: flat static safety stock
                    resin: `ignore`,            // Error 5: ignored upstream supply risk
                    scorecard: `otdonly`,       // narrow KPI lens
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const rt = document.getElementById(`rootInput`);
                const sp = document.getElementById(`splitInput`);
                const lp = document.getElementById(`loopInput`);
                if (rt) decisions.root = rt.value;
                if (sp) decisions.split = parseInt(sp.value, 10);
                if (lp) decisions.loop = lp.value;
                if (!Number.isFinite(decisions.split) || decisions.split < 0 || decisions.split > 100) {
                    warn(`warn_split_range`); return false;
                }
            } else if (round === 2) {
                const ct = document.getElementById(`contractInput`);
                const mx = document.getElementById(`mixInput`);
                const sv = document.getElementById(`serviceInput`);
                if (ct) decisions.contract = ct.value;
                if (mx) decisions.mix = parseInt(mx.value, 10);
                if (sv) decisions.service = sv.value;
                if (!Number.isFinite(decisions.mix) || decisions.mix < 0 || decisions.mix > 100) {
                    warn(`warn_mix_range`); return false;
                }
            } else if (round === 3) {
                const so = document.getElementById(`sopInput`);
                const tw = document.getElementById(`towerInput`);
                const ms = document.getElementById(`mesInput`);
                const au = document.getElementById(`autoInput`);
                const pr = document.getElementById(`processInput`);
                if (so) decisions.sop = parseFloat(so.value);
                if (tw) decisions.tower = parseFloat(tw.value);
                if (ms) decisions.mes = parseFloat(ms.value);
                if (au) decisions.auto = parseFloat(au.value);
                if (pr) decisions.process = pr.value;
                const parts = [decisions.sop, decisions.tower, decisions.mes, decisions.auto];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round((decisions.sop + decisions.tower + decisions.mes + decisions.auto) * 100) / 100;
                if (Math.abs(total - this.DIGITAL_SLICE) > 0.001) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 4) {
                const sf = document.getElementById(`safetyInput`);
                const rs = document.getElementById(`resinInput`);
                const sc = document.getElementById(`scorecardInput`);
                const cv = document.getElementById(`convictionInput`);
                if (sf) decisions.safety = sf.value;
                if (rs) decisions.resin = rs.value;
                if (sc) decisions.scorecard = sc.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let otdDelta = 0, invDelta = 0, utilDelta = 0, costDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the system, not the symptom (Common Error framing).
                switch (d.root) {
                    case `system`:
                        ds.bullwhipDamped = true;
                        otdDelta += 4; invDelta -= 2; coachKey = `coach_r1_system`; break;
                    case `capacity`:
                        // Recency reflex — sets up the wrong R2.
                        invDelta += 1; coachKey = `coach_r1_capacity`; break;
                    case `supplier`:
                        coachKey = `coach_r1_supplier`; break;
                    case `badluck`:
                        otdDelta -= 2; invDelta += 1; coachKey = `coach_r1_badluck`; break;
                }

                // Naming the feedback loop.
                switch (d.loop) {
                    case `bullwhip`: ds.bullwhipDamped = true; otdDelta += 2; invDelta -= 3; break;
                    case `penalty`: break;
                    case `none`: invDelta += 2; coachKey = (d.root === `system`) ? coachKey : `coach_r1_noloop`; break;
                }

                // Attributing self-inflicted variability: the data say a large share is self-inflicted.
                // ~45-70% is the well-calibrated band; under-attributing keeps you reactive.
                if (d.split >= 45 && d.split <= 75) { otdDelta += 2; invDelta -= 2; }
                else if (d.split < 30) { invDelta += 1; coachKey = (coachKey === `coach_default`) ? `coach_r1_underattribute` : coachKey; }

                summaryKey = (d.root === `system` && d.loop === `bullwhip`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Set capacity under volatile demand (Common Errors 1 & 3).
                const permShare = d.mix / 100;

                // Contract go/no-go.
                if (d.contract === `signnow`) {
                    // Growth before stability: a demanding anchor client on a system already at 81% OTD.
                    ds.boughtContract = true;
                    costDelta += 1.5;                 // some revenue contribution booked optimistically
                    otdDelta -= 6; coachKey = `coach_r2_signnow`;
                    if (ds.otd < 90) otdDelta -= 4;   // can't serve today's volatility -> penalties multiply
                } else if (d.contract === `decline`) {
                    // Safe but leaves USD 14M on the table.
                    costDelta -= 0.5; coachKey = `coach_r2_decline`;
                } else { // conditional
                    ds.boughtContract = true;
                    otdDelta += 2; costDelta += 0.8; coachKey = `coach_r2_conditional`;
                }

                // Permanent vs flexible capacity mix. Heavy permanent = fixed cost across slow months.
                if (permShare >= 0.7) {
                    ds.capacityFixed = true;
                    spend += 4.0;                     // ~USD 4M permanent third line (decision tree)
                    utilDelta -= 14;                  // average utilization drops further across slow months
                    costDelta -= 3.0;                 // fixed cost carried 11 slow months
                    otdDelta += 5;                    // it does buy peak service
                    coachKey = `coach_r2_permanent`;
                } else if (permShare <= 0.3) {
                    spend += 1.2;                     // mostly flexible: overtime, temp lines, contract mfg
                    utilDelta += 2;
                    costDelta -= 0.6;
                    otdDelta += 6;                    // flexes to peaks without the fixed-cost drag
                    if (coachKey === `coach_default` || coachKey === `coach_r2_conditional`) coachKey = `coach_r2_flexible`;
                } else {
                    spend += 2.4;                     // balanced mix
                    utilDelta -= 4; costDelta -= 1.2; otdDelta += 5;
                }

                // Size to a distribution & service level, or to a point forecast / absolute peak.
                switch (d.service) {
                    case `distribution`: otdDelta += 6; invDelta -= 2; costDelta += 0.5; break;
                    case `point`: otdDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r2_point` : coachKey; break;
                    case `peak`: costDelta -= 1.5; utilDelta -= 6; coachKey = (coachKey === `coach_default`) ? `coach_r2_peak` : coachKey; break;
                }

                summaryKey = (permShare <= 0.5 && d.service === `distribution` && d.contract !== `signnow`) ? `sum_r2_good` :
                             (ds.capacityFixed ? `sum_r2_fixed` : `sum_r2_weak`);
            } else if (round === 3) {
                // Choose the digitalization investment (Common Error 4: throughput over information).
                const sop = d.sop, tower = d.tower, mes = d.mes, auto = d.auto;
                spend += this.DIGITAL_SLICE;          // the full digital slice is committed

                // Information-centric tools attack the bullwhip & supply risk (the binding constraint).
                otdDelta += sop * 4 + tower * 3 + mes * 2 + auto * 1;
                invDelta -= sop * 3 + tower * 2 + mes * 1 + auto * 0.5;
                // Control tower also buys down the resin exposure.
                if (tower >= 1.0) { ds.resinExposed = false; otdDelta += 2; }
                // Throughput-centric automation raises utilization a bit but doesn't fix the signal.
                utilDelta += auto * 2 - sop * 0.5;
                // Over-investing in automation when the constraint is decision quality.
                if (auto >= 1.5 && sop < 0.5) { otdDelta -= 3; coachKey = `coach_r3_throughput`; }

                // The decision process the technology enables.
                switch (d.process) {
                    case `sop`: ds.bullwhipDamped = true; otdDelta += 5; invDelta -= 4; break;
                    case `reports`: otdDelta += 1; break;
                    case `none`: otdDelta -= 4; invDelta += 2; coachKey = (coachKey === `coach_default`) ? `coach_r3_noprocess` : coachKey; break;
                }

                const infoSpend = sop + tower;
                if (coachKey === `coach_default`) {
                    coachKey = (infoSpend >= 2.0) ? `coach_r3_information` : `coach_r3_mixed`;
                }

                summaryKey = (infoSpend >= 2.0 && d.process === `sop`) ? `sum_r3_good` :
                             (auto >= 1.5 ? `sum_r3_throughput` : `sum_r3_weak`);
            } else if (round === 4) {
                // Redesign buffers & defend the plan (Common Error 5: static buffers / ignored supply risk).
                switch (d.safety) {
                    case `statistical`:
                        otdDelta += 6; invDelta -= 10; costDelta += 0.6; coachKey = `coach_r4_statistical`; break;
                    case `flat`:
                        // Over-stocks stable items, under-protects volatile ones — worst of both.
                        otdDelta -= 2; invDelta -= 3; coachKey = `coach_r4_flat`; break;
                    case `cut`:
                        // Slash everything: hits 30 days but craters service on volatile SKUs.
                        invDelta -= 14; otdDelta -= 8; coachKey = `coach_r4_cut`; break;
                }

                // Single-sourced resin risk.
                switch (d.resin) {
                    case `dualsource`:
                        ds.resinExposed = false; otdDelta += 5; costDelta -= 0.4; break;
                    case `stockpile`:
                        ds.resinExposed = false; invDelta += 8; costDelta -= 0.8; coachKey = `coach_r4_stockpile`; break;
                    case `ignore`:
                        otdDelta -= 6; coachKey = `coach_r4_ignoreresin`; break;
                }

                // KPI scorecard.
                switch (d.scorecard) {
                    case `balanced`: otdDelta += 3; invDelta -= 2; costDelta += 0.3; break;
                    case `otdonly`: invDelta += 3; coachKey = (coachKey === `coach_default`) ? `coach_r4_otdonly` : coachKey; break;
                    case `costonly`: otdDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r4_costonly` : coachKey; break;
                }

                if (d.conviction >= 60 && ds.bullwhipDamped) { otdDelta += 3; }
                else if (d.conviction >= 80 && !ds.bullwhipDamped) { otdDelta -= 2; coachKey = `coach_r4_overconfident`; }

                if (d.safety === `statistical` && d.resin === `dualsource` && d.scorecard === `balanced`) {
                    coachKey = `coach_r4_integrated`;
                }

                summaryKey = (d.safety === `statistical` && d.resin === `dualsource` && d.scorecard === `balanced`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Working-capital cost from inventory above target (~USD 60k / extra day).
            // Apply inventory move first so the cost reflects the new level.
            ds.inv = Math.max(12, Math.round(ds.inv + invDelta));
            const excessDays = Math.max(0, ds.inv - this.INV_TARGET);
            // Carrying-cost drag scales with how far above target we still sit (charged per round).
            costDelta -= excessDays * this.WC_PER_DAY;

            // Apply remaining deltas with clamps.
            ds.otd = Math.max(40, Math.min(99, Math.round((ds.otd + otdDelta) * 10) / 10));
            ds.util = Math.max(40, Math.min(110, Math.round(ds.util + utilDelta)));
            ds.cost = Math.round((ds.cost + costDelta) * 10) / 10;

            ds.budgetUsed = Math.min(this.BUDGET, Math.round((ds.budgetUsed + spend) * 10) / 10);

            ds.otdHistory.push(ds.otd);
            ds.invHistory.push(ds.inv);
            ds.utilHistory.push(ds.util);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0: persist the composite where results_utils.php reads it (per-period + final).
            const _score = this._composite(ds);
            ds.score = _score;
            if (!ds.performance || typeof ds.performance !== `object`) { ds.performance = {}; }
            ds.performance.overallScore = _score;

            return {
                period: state.currentPeriod,
                score: _score,
                otd: ds.otd,
                otdDelta: Math.round(otdDelta * 10) / 10,
                inv: ds.inv,
                invDelta: Math.round(invDelta),
                util: ds.util,
                utilDelta: Math.round(utilDelta),
                cost: ds.cost,
                costDelta: Math.round(costDelta * 10) / 10,
                budgetUsed: ds.budgetUsed,
                resinExposed: ds.resinExposed,
                capacityFixed: ds.capacityFixed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // Locale-aware USD: English "$2.4M" (symbol before), Spanish "2,4 M$" (symbol after, comma decimal).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(1).replace(`.`, `,`)} M$`;
            }
            return `${sign}$${abs.toFixed(1)}M`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`otdDisplay`, `domainState.otd`, (v) => {
                const card = document.querySelector(`.opsim-card-otd`);
                if (card) {
                    card.classList.toggle(`opsim-otd-good`, Number(v) >= 96);
                    card.classList.toggle(`opsim-otd-bad`, Number(v) < 85);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`invDisplay`, `domainState.inv`, (v) => {
                const card = document.querySelector(`.opsim-card-inv`);
                if (card) {
                    card.classList.toggle(`opsim-inv-good`, Number(v) <= 34);
                    card.classList.toggle(`opsim-inv-bad`, Number(v) >= 45);
                }
                return Math.round(Number(v)) + `d`;
            });
            uiManager.bind(`utilDisplay`, `domainState.util`, (v) => Math.round(Number(v)) + `%`);
            uiManager.bind(`costDisplay`, `domainState.cost`, (v) => {
                const card = document.querySelector(`.opsim-card-cost`);
                if (card) {
                    card.classList.toggle(`opsim-cost-positive`, Number(v) > 0.05);
                    card.classList.toggle(`opsim-cost-negative`, Number(v) < -0.05);
                }
                return self._fmtMoney(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                return self._fmtMoney(Number(v)) + ` / ` + self._fmtMoney(self.BUDGET);
            });

            // Self-inflicted-share slider readout.
            const sp = document.getElementById(`splitInput`);
            const spReadout = document.getElementById(`splitReadout`);
            if (sp && spReadout) {
                spReadout.textContent = sp.value;
                sp.addEventListener(`input`, function() { spReadout.textContent = sp.value; });
            }

            // Permanent-capacity-share slider readout.
            const mx = document.getElementById(`mixInput`);
            const mxReadout = document.getElementById(`mixReadout`);
            if (mx && mxReadout) {
                mxReadout.textContent = mx.value;
                mx.addEventListener(`input`, function() { mxReadout.textContent = mx.value; });
            }

            // Digital-budget live total (must hit USD 3.0M).
            const allocIds = [`sopInput`, `towerInput`, `mesInput`, `autoInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 100) / 100;
                if (allocReadout) allocReadout.textContent = total.toFixed(1);
                const bar = document.querySelector(`.opsim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.DIGITAL_SLICE) > 0.001) ? `#ff6b5e` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

