        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.otdHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                opsChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.otdHistory },
                        { data: ds.invHistory },
                        { data: ds.utilHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0: verbatim v1.0.0 formula, extracted so calculateResults can persist it every period.
            const otd = Math.round(ds.otd);
            const inv = Math.round(ds.inv);
            const util = Math.round(ds.util);
            const cost = ds.cost;
            const invScore = Math.max(0, 100 - Math.abs(inv - this.INV_TARGET) * 4);
            const utilScore = Math.max(0, 100 - Math.abs(util - 86) * 3);
            const costScore = Math.max(0, Math.min(100, 50 + cost * 8));
            return Math.round(otd * 0.38 + invScore * 0.24 + utilScore * 0.14 + costScore * 0.24);
        }

        formatCompletionMessage(summary) {
            // v1.1.0: localized debrief; without this override the engine discards score/tier/insights.
            const t = (k) => (window.mySimulation ? window.mySimulation.t(k) : k);
            if (!summary || typeof summary.composite === `undefined`) {
                return `<div class="ops-cm"><div class="ops-cm-tier">${t(`grade_bullwhip`)}</div></div>`;
            }
            const tier = summary.performance || t(summary.performanceKey || `grade_bullwhip`);
            const chip = (ok, label) => `<div class="ops-cm-chip ${ok ? `is-met` : `is-missed`}"><span class="ops-cm-chip-l">${label}</span><span class="ops-cm-badge ${ok ? `is-met` : `is-missed`}">${ok ? t(`cm_met`) : t(`cm_missed`)}</span></div>`;
            const lis = (summary.insights || []).map((s) => `<li>${s}</li>`).join(``);
            return `
                <div class="ops-cm">
                    <div class="ops-cm-head">
                        <div class="ops-cm-scorebox">
                            <div class="ops-cm-score">${summary.composite}<span class="ops-cm-score-max">/100</span></div>
                            <div class="ops-cm-score-label">${t(`cm_score_label`)}</div>
                        </div>
                        <div class="ops-cm-tier">${tier}</div>
                    </div>
                    <div class="ops-cm-chips">
                        ${chip(summary.served, t(`cm_chip_served`))}
                        ${chip(summary.lean, t(`cm_chip_lean`))}
                        ${chip(summary.resilient, t(`cm_chip_resilient`))}
                    </div>
                    <div class="ops-cm-kpis">
                        <div class="ops-cm-kpi"><div class="ops-cm-kpi-v">${summary.otd}%</div><div class="ops-cm-kpi-l">${t(`cm_kpi_otd`)}</div></div>
                        <div class="ops-cm-kpi"><div class="ops-cm-kpi-v">${summary.inv}</div><div class="ops-cm-kpi-l">${t(`cm_kpi_inv`)}</div></div>
                        <div class="ops-cm-kpi"><div class="ops-cm-kpi-v">${summary.util}%</div><div class="ops-cm-kpi-l">${t(`cm_kpi_util`)}</div></div>
                        <div class="ops-cm-kpi"><div class="ops-cm-kpi-v">${this._fmtMoney(Number(summary.cost))}</div><div class="ops-cm-kpi-l">${t(`cm_kpi_cost`)}</div></div>
                    </div>
                    <div class="ops-cm-insights">
                        <div class="ops-cm-insights-title">${t(`cm_insights_title`)}</div>
                        <ul>${lis}</ul>
                    </div>
                </div>
            `;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const otd = Math.round(ds.otd);
            const inv = Math.round(ds.inv);
            const util = Math.round(ds.util);
            const cost = ds.cost;

            // Composite: service, inventory-toward-target, utilization-health, cost.
            // v1.1.0: composite via _composite(ds) — single source of truth, value byte-identical to v1.0.0.
            const composite = this._composite(ds);

            const served = otd >= 94;
            const lean = inv <= 36;
            const resilient = !ds.resinExposed && ds.bullwhipDamped;
            const overbuilt = ds.capacityFixed && util < 75;
            const exposed = ds.resinExposed || (!ds.bullwhipDamped && otd < 90);

            // v1.1.0: tier is now i18n-keyed (was hardcoded English) so it localizes.
            let performanceKey = `grade_bullwhip`;
            if (served && lean && resilient && composite >= 75) performanceKey = `grade_stabilized`;
            else if (served && lean) performanceKey = `grade_targets`;
            else if (overbuilt) performanceKey = `grade_overbuilt`;
            else if (exposed) performanceKey = `grade_exposed`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (served && lean && resilient) insights.push(window.mySimulation.t(`insight_stabilized`));
            else if (exposed) insights.push(window.mySimulation.t(`insight_exposed`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.capacityFixed && util < 75) insights.push(window.mySimulation.t(`insight_overbuilt`));
            if (ds.resinExposed) insights.push(window.mySimulation.t(`insight_resin`));
            if (otd < 90) insights.push(window.mySimulation.t(`insight_service`));
            else if (otd >= 96) insights.push(window.mySimulation.t(`insight_servicemet`));
            if (inv > 42) insights.push(window.mySimulation.t(`insight_inventory`));
            if (cost < -4) insights.push(window.mySimulation.t(`insight_cost`));

            return {
                totalPeriods: history.length,
                otd: otd,
                inv: inv,
                util: util,
                cost: cost,
                served: served,
                lean: lean,
                resilient: resilient,
                composite: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.capacityFixed && ds.util < 72) return window.mySimulation.t(`hint_overbuilt`);
            if (ds.inv >= 46) return window.mySimulation.t(`hint_inventory`);
            if (ds.resinExposed && state.currentPeriod >= 3) return window.mySimulation.t(`hint_resin`);
            if (ds.otd < 88) return window.mySimulation.t(`hint_service`);
            if (!ds.bullwhipDamped && state.currentPeriod >= 2) return window.mySimulation.t(`hint_bullwhip`);
            if (ds.otd >= 96 && ds.inv <= 34 && !ds.resinExposed) return window.mySimulation.t(`hint_strong`);
            return null;
        }

