                    warn_split_range:       `La parte autoinfligida debe ser un porcentaje entre 0 y 100.`,
                    warn_mix_range:         `La porción de capacidad permanente debe ser un porcentaje entre 0 y 100.`,
                    warn_alloc_negative:    `Las asignaciones del presupuesto digital no pueden ser negativas.`,
